"use client";

import { useRouter, useSearchParams } from "next/navigation";
import { Category, getCategories } from "@/lib/products";
import { useState } from "react";
import { SlidersHorizontal, X } from "lucide-react";

const SORT_OPTIONS = [
  { value: "newest",     label: "Newest" },
  { value: "price-asc",  label: "Price: Low to High" },
  { value: "price-desc", label: "Price: High to Low" },
  { value: "rating",     label: "Top Rated" },
];

export default function FilterSidebar() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const [open, setOpen] = useState(false);

  const activeCategory = searchParams.get("category") as Category | null;
  const activeSort = searchParams.get("sort") ?? "newest";

  const categories = getCategories();

  function updateParams(key: string, value: string | null) {
    const params = new URLSearchParams(searchParams.toString());
    if (value) {
      params.set(key, value);
    } else {
      params.delete(key);
    }
    router.push(`/shop?${params.toString()}`);
  }

  const sidebarContent = (
    <div className="flex flex-col gap-8">
      {/* Sort */}
      <div>
        <h3 className="text-[10px] tracking-widest uppercase text-[var(--text-muted)] mb-4">
          Sort By
        </h3>
        <div className="flex flex-col gap-3">
          {SORT_OPTIONS.map((opt) => (
            <button
              key={opt.value}
              onClick={() => updateParams("sort", opt.value)}
              className={`text-left text-sm transition-colors duration-200 ${
                activeSort === opt.value
                  ? "text-[var(--gold-primary)]"
                  : "text-[var(--text-secondary)] hover:text-[var(--text-primary)]"
              }`}
            >
              {activeSort === opt.value && (
                <span className="mr-2 text-[var(--gold-primary)]">—</span>
              )}
              {opt.label}
            </button>
          ))}
        </div>
      </div>

      {/* Categories */}
      <div>
        <h3 className="text-[10px] tracking-widest uppercase text-[var(--text-muted)] mb-4">
          Category
        </h3>
        <div className="flex flex-col gap-3">
          <button
            onClick={() => updateParams("category", null)}
            className={`text-left text-sm transition-colors duration-200 ${
              !activeCategory
                ? "text-[var(--gold-primary)]"
                : "text-[var(--text-secondary)] hover:text-[var(--text-primary)]"
            }`}
          >
            {!activeCategory && <span className="mr-2">—</span>}
            All
          </button>
          {categories.map((cat) => (
            <button
              key={cat}
              onClick={() =>
                updateParams("category", activeCategory === cat ? null : cat)
              }
              className={`text-left text-sm transition-colors duration-200 ${
                activeCategory === cat
                  ? "text-[var(--gold-primary)]"
                  : "text-[var(--text-secondary)] hover:text-[var(--text-primary)]"
              }`}
            >
              {activeCategory === cat && (
                <span className="mr-2 text-[var(--gold-primary)]">—</span>
              )}
              {cat}
            </button>
          ))}
        </div>
      </div>
    </div>
  );

  return (
    <>
      {/* Mobile filter button */}
      <div className="flex md:hidden items-center justify-between mb-6">
        <button
          onClick={() => setOpen(true)}
          className="flex items-center gap-2 text-xs tracking-widest uppercase text-[var(--text-secondary)] border border-[var(--border-default)] px-4 py-2 hover:border-[var(--border-gold)] hover:text-[var(--gold-primary)] transition-colors duration-300"
        >
          <SlidersHorizontal size={14} />
          Filter & Sort
        </button>
        {activeCategory && (
          <button
            onClick={() => updateParams("category", null)}
            className="flex items-center gap-1 text-xs text-[var(--gold-primary)] border border-[var(--border-gold)] px-3 py-2"
          >
            {activeCategory} <X size={12} />
          </button>
        )}
      </div>

      {/* Mobile off-canvas */}
      {open && (
        <>
          <div
            className="fixed inset-0 bg-black/70 z-40 animate-fade-in md:hidden"
            onClick={() => setOpen(false)}
          />
          <div className="fixed left-0 top-0 h-full w-72 bg-[var(--bg-surface)] z-50 flex flex-col animate-slide-in-left border-r border-[var(--border-gold)] md:hidden">
            <div className="flex items-center justify-between px-6 py-5 border-b border-[var(--border-default)]">
              <span className="text-xs tracking-widest uppercase text-[var(--text-secondary)]">
                Filter & Sort
              </span>
              <button onClick={() => setOpen(false)}>
                <X size={18} className="text-[var(--text-secondary)]" />
              </button>
            </div>
            <div className="px-6 py-6 flex-1 overflow-y-auto">{sidebarContent}</div>
          </div>
        </>
      )}

      {/* Desktop sticky sidebar */}
      <div className="hidden md:block w-48 shrink-0 sticky top-24 self-start">
        {sidebarContent}
      </div>
    </>
  );
}

import { Suspense } from "react";
import { getProducts, Category } from "@/lib/products";
import ProductCard from "@/components/ProductCard";
import FilterSidebar from "@/components/FilterSidebar";

type SearchParams = {
  category?: string;
  sort?: string;
  priceMin?: string;
  priceMax?: string;
};

function ProductGridSkeleton() {
  return (
    <div className="grid grid-cols-2 md:grid-cols-3 gap-4 flex-1">
      {Array.from({ length: 6 }).map((_, i) => (
        <div
          key={i}
          className="aspect-[3/4] bg-[var(--bg-surface)] animate-pulse border border-[var(--border-default)]"
        />
      ))}
    </div>
  );
}

async function ProductGrid({ searchParams }: { searchParams: SearchParams }) {
  const products = getProducts({
    category: searchParams.category as Category | undefined,
    sort: searchParams.sort as "price-asc" | "price-desc" | "newest" | "rating" | undefined,
    priceMin: searchParams.priceMin ? Number(searchParams.priceMin) : undefined,
    priceMax: searchParams.priceMax ? Number(searchParams.priceMax) : undefined,
  });

  if (products.length === 0) {
    return (
      <div className="flex-1 flex flex-col items-center justify-center py-32 text-center">
        <p className="font-[family-name:var(--font-cormorant)] text-3xl font-light italic text-[var(--text-secondary)] mb-4">
          No pieces found
        </p>
        <p className="text-sm text-[var(--text-muted)]">
          Try adjusting your filters
        </p>
      </div>
    );
  }

  return (
    <div className="grid grid-cols-2 md:grid-cols-3 gap-4 flex-1">
      {products.map((product, i) => (
        <div
          key={product.id}
          className="animate-fade-up"
          style={{ animationDelay: `${i * 60}ms` }}
        >
          <ProductCard product={product} index={i} />
        </div>
      ))}
    </div>
  );
}

export default async function ShopPage({
  searchParams,
}: {
  searchParams: Promise<SearchParams>;
}) {
  const params = await searchParams;

  return (
    <div className="max-w-7xl mx-auto px-6 pt-28 pb-24">
      {/* Page header */}
      <div className="mb-12">
        <p className="text-xs tracking-widest uppercase text-[var(--gold-primary)] mb-2">
          {params.category ?? "All Pieces"}
        </p>
        <h1 className="font-[family-name:var(--font-cormorant)] text-5xl font-light italic text-[var(--text-primary)]">
          The Collection
        </h1>
      </div>

      <div className="flex flex-col md:flex-row gap-10">
        <FilterSidebar />

        <Suspense fallback={<ProductGridSkeleton />}>
          <ProductGrid searchParams={params} />
        </Suspense>
      </div>
    </div>
  );
}

