@import "tailwindcss";

/* ─── Design Tokens ─────────────────────────────────────────── */
:root {
  /* Backgrounds */
  --bg-base:       #0A0A0A;
  --bg-surface:    #111111;
  --bg-elevated:   #1A1A1A;
  --bg-overlay:    rgba(0, 0, 0, 0.7);

  /* Gold palette */
  --gold-primary:  #D4AF37;
  --gold-muted:    #B8960C;
  --gold-subtle:   rgba(212, 175, 55, 0.12);

  /* Text */
  --text-primary:  #F5F0E8;
  --text-secondary:#A09880;
  --text-muted:    #5A5040;

  /* Borders */
  --border-default:#2A2520;
  --border-gold:   rgba(212, 175, 55, 0.3);

  /* Functional */
  --success:       #4CAF7A;
  --error:         #E05A5A;
}

/* ─── Tailwind v4 Theme Extension ───────────────────────────── */
@theme inline {
  --font-display: var(--font-cormorant);
  --font-body:    var(--font-geist-sans);

  --color-base:        var(--bg-base);
  --color-surface:     var(--bg-surface);
  --color-elevated:    var(--bg-elevated);
  --color-gold:        var(--gold-primary);
  --color-gold-muted:  var(--gold-muted);
  --color-primary:     var(--text-primary);
  --color-secondary:   var(--text-secondary);
  --color-muted:       var(--text-muted);
  --color-border:      var(--border-default);
}

/* ─── Base Styles ───────────────────────────────────────────── */
body {
  background: var(--bg-base);
  color: var(--text-primary);
  font-family: var(--font-body), Arial, Helvetica, sans-serif;
  font-weight: 400;
  letter-spacing: 0.01em;
  line-height: 1.6;
}

* {
  box-sizing: border-box;
}

/* ─── Keyframes ─────────────────────────────────────────────── */
@keyframes fade-up {
  from {
    opacity: 0;
    transform: translateY(24px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes slide-in-right {
  from { transform: translateX(100%); }
  to   { transform: translateX(0); }
}

@keyframes slide-out-right {
  from { transform: translateX(0); }
  to   { transform: translateX(100%); }
}

@keyframes slide-in-left {
  from { transform: translateX(-100%); }
  to   { transform: translateX(0); }
}

@keyframes slide-out-left {
  from { transform: translateX(0); }
  to   { transform: translateX(-100%); }
}

@keyframes fade-in {
  from { opacity: 0; }
  to   { opacity: 1; }
}

@keyframes fade-out {
  from { opacity: 1; }
  to   { opacity: 0; }
}

@keyframes letterspace-in {
  from {
    letter-spacing: 0.4em;
    opacity: 0;
  }
  to {
    letter-spacing: 0.05em;
    opacity: 1;
  }
}

@keyframes marquee {
  from { transform: translateX(0); }
  to   { transform: translateX(-50%); }
}

@keyframes shimmer {
  from { background-position: -200% center; }
  to   { background-position:  200% center; }
}

@keyframes pulse-dot {
  0%, 100% { transform: scale(1);   opacity: 1; }
  50%       { transform: scale(1.4); opacity: 0.6; }
}

/* ─── Utility Classes ───────────────────────────────────────── */
@layer utilities {
  .animate-fade-up {
    animation: fade-up 0.6s cubic-bezier(0.16, 1, 0.3, 1) both;
  }

  .animate-slide-in-right {
    animation: slide-in-right 0.4s cubic-bezier(0.16, 1, 0.3, 1) both;
  }

  .animate-slide-out-right {
    animation: slide-out-right 0.4s cubic-bezier(0.16, 1, 0.3, 1) both;
  }

  .animate-slide-in-left {
    animation: slide-in-left 0.4s cubic-bezier(0.16, 1, 0.3, 1) both;
  }

  .animate-slide-out-left {
    animation: slide-out-left 0.4s cubic-bezier(0.16, 1, 0.3, 1) both;
  }

  .animate-fade-in {
    animation: fade-in 0.3s ease both;
  }

  .animate-fade-out {
    animation: fade-out 0.3s ease both;
  }

  .animate-letterspace-in {
    animation: letterspace-in 1s cubic-bezier(0.16, 1, 0.3, 1) both;
  }

  .animate-marquee {
    animation: marquee 25s linear infinite;
  }

  /* Stagger delays */
  .delay-100 { animation-delay: 100ms; }
  .delay-200 { animation-delay: 200ms; }
  .delay-300 { animation-delay: 300ms; }
  .delay-400 { animation-delay: 400ms; }
  .delay-500 { animation-delay: 500ms; }
  .delay-600 { animation-delay: 600ms; }
  .delay-700 { animation-delay: 700ms; }
  .delay-800 { animation-delay: 800ms; }

  /* Gold gradient text */
  .text-gold-gradient {
    background: linear-gradient(
      90deg,
      var(--gold-muted),
      var(--gold-primary),
      var(--gold-muted)
    );
    background-size: 200% auto;
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }

  .text-gold-gradient-shimmer {
    background: linear-gradient(
      90deg,
      var(--gold-muted),
      var(--gold-primary),
      var(--gold-muted)
    );
    background-size: 200% auto;
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    animation: shimmer 3s linear infinite;
  }

  /* Hide scrollbar */
  .scrollbar-hide {
    scrollbar-width: none;
  }
  .scrollbar-hide::-webkit-scrollbar {
    display: none;
  }

  /* Gold border glow */
  .border-gold-glow {
    border-color: var(--border-gold);
    box-shadow: 0 0 0 1px var(--border-gold);
  }

  /* Smooth underline on hover */
  .link-underline {
    position: relative;
  }
  .link-underline::after {
    content: "";
    position: absolute;
    bottom: -2px;
    left: 0;
    width: 0;
    height: 1px;
    background: var(--gold-primary);
    transition: width 0.3s ease;
  }
  .link-underline:hover::after {
    width: 100%;
  }
}

import { Suspense } from "react";
import { getProducts, Category } from "@/lib/products";
import ProductCard from "@/components/ProductCard";
import FilterSidebar from "@/components/FilterSidebar";

export const instant = false;

type SearchParams = {
  category?: string;
  sort?: string;
  priceMin?: string;
  priceMax?: string;
};

function ProductGridSkeleton() {
  return (
    <div className="grid grid-cols-2 md:grid-cols-3 gap-4 flex-1">
      {Array.from({ length: 6 }).map((_, i) => (
        <div
          key={i}
          className="aspect-[3/4] bg-[var(--bg-surface)] animate-pulse border border-[var(--border-default)]"
        />
      ))}
    </div>
  );
}

async function ProductGrid({ searchParams }: { searchParams: SearchParams }) {
  const products = getProducts({
    category: searchParams.category as Category | undefined,
    sort: searchParams.sort as "price-asc" | "price-desc" | "newest" | "rating" | undefined,
    priceMin: searchParams.priceMin ? Number(searchParams.priceMin) : undefined,
    priceMax: searchParams.priceMax ? Number(searchParams.priceMax) : undefined,
  });

  if (products.length === 0) {
    return (
      <div className="flex-1 flex flex-col items-center justify-center py-32 text-center">
        <p className="font-[family-name:var(--font-cormorant)] text-3xl font-light italic text-[var(--text-secondary)] mb-4">
          No pieces found
        </p>
        <p className="text-sm text-[var(--text-muted)]">
          Try adjusting your filters
        </p>
      </div>
    );
  }

  return (
    <div className="grid grid-cols-2 md:grid-cols-3 gap-4 flex-1">
      {products.map((product, i) => (
        <div
          key={product.id}
          className="animate-fade-up"
          style={{ animationDelay: `${i * 60}ms` }}
        >
          <ProductCard product={product} index={i} />
        </div>
      ))}
    </div>
  );
}

export default async function ShopPage({
  searchParams,
}: {
  searchParams: Promise<SearchParams>;
}) {
  const params = await searchParams;

  return (
    <div className="max-w-7xl mx-auto px-6 pt-28 pb-24">
      {/* Page header */}
      <div className="mb-12">
        <p className="text-xs tracking-widest uppercase text-[var(--gold-primary)] mb-2">
          {params.category ?? "All Pieces"}
        </p>
        <h1 className="font-[family-name:var(--font-cormorant)] text-5xl font-light italic text-[var(--text-primary)]">
          The Collection
        </h1>
      </div>

      <div className="flex flex-col md:flex-row gap-10">
        <Suspense fallback={<div className="hidden md:block w-48 shrink-0" />}>
          <FilterSidebar />
        </Suspense>

        <Suspense fallback={<ProductGridSkeleton />}>
          <ProductGrid searchParams={params} />
        </Suspense>
      </div>
    </div>
  );
}

import { notFound } from "next/navigation";
import Link from "next/link";
import type { Metadata } from "next";
import {
  getProductBySlug,
  getRelatedProducts,
  getStaticProductParams,
} from "@/lib/products";
import ImageGallery from "@/components/ImageGallery";
import ProductCard from "@/components/ProductCard";
import ProductActions from "./ProductActions";

type Props = {
  params: Promise<{ slug: string }>;
};

export async function generateStaticParams() {
  return getStaticProductParams();
}

export async function generateMetadata({ params }: Props): Promise<Metadata> {
  const { slug } = await params;
  const product = getProductBySlug(slug);
  if (!product) return { title: "Product Not Found" };
  return {
    title: `${product.name} — MAISON NOIR`,
    description: product.description,
  };
}

export default async function ProductDetailPage({ params }: Props) {
  const { slug } = await params;
  const product = getProductBySlug(slug);

  if (!product) notFound();

  const related = getRelatedProducts(product, 4);

  return (
    <div className="pt-20">
      {/* Breadcrumb */}
      <div className="max-w-7xl mx-auto px-6 py-6">
        <nav className="flex items-center gap-2 text-xs tracking-wider text-[var(--text-muted)]">
          <Link href="/" className="hover:text-[var(--gold-primary)] transition-colors">
            Home
          </Link>
          <span>/</span>
          <Link href="/shop" className="hover:text-[var(--gold-primary)] transition-colors">
            Shop
          </Link>
          <span>/</span>
          <Link
            href={`/shop?category=${product.category}`}
            className="hover:text-[var(--gold-primary)] transition-colors"
          >
            {product.category}
          </Link>
          <span>/</span>
          <span className="text-[var(--text-secondary)]">{product.name}</span>
        </nav>
      </div>

      {/* Main product layout */}
      <div className="max-w-7xl mx-auto px-6 pb-24">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-12 lg:gap-20">
          {/* Gallery */}
          <ImageGallery images={product.images} name={product.name} />

          {/* Info + Actions */}
          <div className="md:sticky md:top-24 self-start">
            <ProductActions product={product} />
          </div>
        </div>

        {/* Related products */}
        {related.length > 0 && (
          <section className="mt-24 pt-12 border-t border-[var(--border-default)]">
            <div className="flex items-end justify-between mb-10">
              <div>
                <p className="text-xs tracking-widest uppercase text-[var(--gold-primary)] mb-2">
                  You May Also Like
                </p>
                <h2 className="font-[family-name:var(--font-cormorant)] text-3xl font-light italic">
                  More {product.category}
                </h2>
              </div>
              <Link
                href={`/shop?category=${product.category}`}
                className="text-xs tracking-widest uppercase text-[var(--text-secondary)] hover:text-[var(--gold-primary)] transition-colors link-underline hidden sm:block"
              >
                View All
              </Link>
            </div>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              {related.map((p, i) => (
                <ProductCard key={p.id} product={p} index={i} />
              ))}
            </div>
          </section>
        )}
      </div>
    </div>
  );
}

